const { chromium } = require('playwright');
const path = require('path');

(async () => {
  let browser;
  try {
    browser = await chromium.launch();
    const page = await browser.newPage();
    const filePath = 'file://' + path.resolve('index.html');
    await page.goto(filePath, { waitUntil: 'networkidle' });

    // Wait for React to render
    await page.waitForSelector('.example', { timeout: 10000 });

    // Inject axe-core
    await page.addScriptTag({ path: path.resolve('node_modules/axe-core/axe.min.js') });

    const r = await page.evaluate(async () => {
      return await window.axe.run();
    });

    const wcag = r.violations.filter(v => !v.tags.includes('best-practice'));
    const bp = r.violations.filter(v => v.tags.includes('best-practice'));

    console.log(JSON.stringify({
      wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
      bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
    }));

    process.exit(wcag.length > 0 ? 1 : 0);
  } catch (err) {
    console.error(err);
    process.exit(1);
  } finally {
    if (browser) await browser.close();
  }
})();

