   return (
     <div className="example">
       <h3>
         <button
           type="button"
           aria-expanded={isOpen}
           onClick={() => setIsOpen(!isOpen)}
         >
           <span>{question}</span>
           <span className="icon" aria-hidden="true">+</span>
         </button>
       </h3>
       <div className="details" hidden={!isOpen}>
         <p>{answer}</p>
       </div>
     </div>
   );
 };

 const App = () => {
   const faqs = [
     {
       question: "Why do cats purr?",
       answer: "While purring often signals contentment, cats also purr to self-soothe when stressed or injured. The frequency of a cat's purr (between 25 and 150 Hertz) has been shown to improve bone density and promote healing."
     },
     {
       question: "Why do cats sleep so much?",
       answer: "Cats are crepuscular, meaning they are most active during dawn and dusk. They sleep an average of 12 to 16 hours a day to conserve energy for the 'hunt,' even if that hunt is just chasing a laser pointer."
     },
     {
       question: "Why do cats knead (or 'make biscuits')?",
       answer: "Kneading is a behavior kittens use to stimulate milk flow from their mothers. Adult cats continue this behavior when they feel safe, comfortable, and happy, often as a way to show affection or mark their territory with scent glands in their paws."
     },
     {
       question: "Can cats see in the dark?",
       answer: "Cats can't see in total darkness, but they can see in one-sixth the light level required for human vision. This is thanks to the tapetum lucidum, a reflective layer behind their retina that gives their eyes that eerie glow in the dark."
     },
     {
       question: "Why do cats hate water?",
       answer: "Most cats dislike water because it weighs down their fur, making them less agile and more vulnerable. Additionally, many cats are sensitive to the smell of chemicals in tap water, though some breeds like the Turkish Van actually enjoy swimming!"
     }
   ];

   return (
     <main>
       <h1>Cat Frequently Asked Questions</h1>
       <div className="faq-list">
         {faqs.map((faq, index) => (
           <FaqItem key={index} question={faq.question} answer={faq.answer} />
         ))}
       </div>
     </main>
   );
 };

 const root = ReactDOM.createRoot(document.getElementById('root'));
 root.render(<App />);

